cut = [r for r in rows if r['finish']=='length']
fin = [r for r in rows if r['finish']=='stop']
def wc(rs):
    c = collections.Counter()
    tot = 0
    for r in rs:
        for w in r['text'].split():
            c[w.strip('.,!?*#:;()[]').lower()] += 1
        tot += len(r['text'].split())
    return c, tot
cc, ct = wc(cut); fc, ft = wc(fin)
for w in ['wait','the','however','but','let','hmm','so','actually','reconsider','no']:
    print(w, cc[w]*1000/ct, fc[w]*1000/ft)
